#include "study_support.h"
extern "C" int study_check(const char*path,double*metrics){try{std::ifstream f(path,std::ios::binary);std::vector<float>v(outcount);f.read((char*)v.data(),v.size()*4);if(!f||f.peek()!=EOF)throw std::runtime_error("artifactsize");size_t pos=0;auto get=[&](){return v.at(pos++);};auto exact=[&](float x){float a=get();if(memcmp(&a,&x,4))throw std::runtime_error("exactinput/header/guard");};double ma=0,mr=0,ind=0;auto near=[&](float x){float a=get();if(!std::isfinite(a))throw std::runtime_error("nonfinite");double e=fabs(double(a)-x),re=x?e/fabs(x):0;ma=std::max(ma,e);mr=std::max(mr,re);if(e>1e-4+1e-5*fabs(x))throw std::runtime_error("treeoracle");return a;};auto cs=cases();exact(3);for(auto&c:cs){exact(c.n);exact(c.repeat);for(float x:c.d)exact(x);}for(auto&c:cs){auto q=tree(c,1);std::vector<float>actual;for(float x:q)actual.push_back(near(x));float mean,a,b;coefficients(actual,c.n,mean,a,b);auto z=tree(c,2,mean,a,b);for(float x:z)near(x);float am=near(mean),aa=near(a),ab=near(b);float sx=0,sy=0;for(size_t i=0;i<z.size();i+=2){sx+=z[i];sy+=z[i+1];}float percent=get();if(!std::isfinite(percent)||fabs(percent-int(sy/sx*100))>1)throw std::runtime_error("rpercent");double X=0,Y=0,XX=0,XY=0;for(int i=0;i<c.n;i++){double x=c.d[2*i],y=c.d[2*i+1];X+=x;Y+=y;XX+=x*x;XY+=x*y;}double B=(c.n*XY-X*Y)/(c.n*XX-X*X),A=(Y-B*X)/c.n;ind=std::max({ind,fabs(aa-A),fabs(ab-B)});if(fabs(aa-A)>1e-4||fabs(ab-B)>1e-4||fabs(am-Y/c.n)>1e-4)throw std::runtime_error("Float64OLS");for(int i=0;i<384;i++)exact(-777.f);}if(pos!=v.size())throw std::runtime_error("count");metrics[0]=ma;metrics[1]=mr;metrics[2]=ind;return 0;}catch(std::exception&e){fprintf(stderr,"LR_CHECK_FAIL %s\n",e.what());return 1;}}
